"use client";

import React, { useState, useEffect } from 'react';
import { Send, Clock, CheckCircle, AlertTriangle, Play, RefreshCw, CalendarDays, Loader2 } from 'lucide-react';
import Link from 'next/link';

export default function PublishingDashboardPage({ params }: { params: { username: string } }) {
  const { username } = params;
  const [queue, setQueue] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isExecuting, setIsExecuting] = useState(false);

  const fetchQueue = () => {
    setIsLoading(true);
    fetch(`/api/workspace/${username}/publishing`)
      .then(r => r.json())
      .then(data => {
        if (data.queue) setQueue(data.queue);
        setIsLoading(false);
      });
  };

  useEffect(() => {
    fetchQueue();
  }, [username]);

  const handleExecuteJob = async () => {
    setIsExecuting(true);
    try {
      const res = await fetch(`/api/workspace/${username}/publishing`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'execute' })
      });
      if (res.ok) {
        const result = await res.json();
        alert(`Job Result: ${result.message}`);
        fetchQueue();
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsExecuting(false);
    }
  };

  const getStatusIcon = (status: string) => {
    switch(status) {
      case 'Scheduled': return <Clock className="w-5 h-5 text-blue-400" />;
      case 'Publishing': return <Loader2 className="w-5 h-5 text-amber-400 animate-spin" />;
      case 'Published': return <CheckCircle className="w-5 h-5 text-emerald-400" />;
      case 'Failed': return <AlertTriangle className="w-5 h-5 text-red-400" />;
      case 'Retrying': return <RefreshCw className="w-5 h-5 text-orange-400" />;
      default: return <Clock className="w-5 h-5 text-slate-400" />;
    }
  };

  const getStatusColor = (status: string) => {
    switch(status) {
      case 'Scheduled': return 'bg-blue-500/10 text-blue-400 border-blue-500/20';
      case 'Publishing': return 'bg-amber-500/10 text-amber-400 border-amber-500/20';
      case 'Published': return 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20';
      case 'Failed': return 'bg-red-500/10 text-red-400 border-red-500/20';
      case 'Retrying': return 'bg-orange-500/10 text-orange-400 border-orange-500/20';
      default: return 'bg-slate-800 text-slate-300 border-slate-700';
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 flex flex-col overflow-hidden">
      {/* Top Navbar */}
      <header className="h-16 border-b border-white/5 flex items-center justify-between px-6 bg-slate-900/50">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 rounded-lg bg-emerald-500/20 border border-emerald-500/30 flex items-center justify-center">
            <Send className="w-4 h-4 text-emerald-400" />
          </div>
          <span className="font-bold text-white tracking-wide">Publishing & Automation</span>
        </div>
        <div className="text-sm text-slate-400">
          Managing Distribution for <span className="text-emerald-300 font-medium">@{username}</span>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 p-8 max-w-7xl mx-auto w-full">
        <div className="flex justify-between items-center mb-8">
          <div>
            <h1 className="text-3xl font-bold text-white mb-2">Publishing Queue</h1>
            <p className="text-slate-400">Monitor your scheduled posts and automation pipelines.</p>
          </div>
          <button 
            onClick={handleExecuteJob}
            disabled={isExecuting}
            className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-500 text-white px-4 py-2 rounded-xl font-medium transition-colors disabled:opacity-50"
          >
            <Play className={`w-4 h-4 ${isExecuting ? 'animate-pulse' : ''}`} /> 
            Trigger Cron Job (Simulate Time)
          </button>
        </div>

        {/* Queue List */}
        {isLoading ? (
          <div className="text-center py-20 text-slate-500"><Loader2 className="w-8 h-8 animate-spin mx-auto mb-4" /> Loading Queue...</div>
        ) : queue.length === 0 ? (
          <div className="text-center py-20 bg-slate-900 border border-white/5 rounded-2xl">
            <CalendarDays className="w-12 h-12 text-slate-700 mx-auto mb-4" />
            <h3 className="text-xl font-bold text-white mb-2">Queue is Empty</h3>
            <p className="text-slate-400 max-w-md mx-auto mb-6">You have no scheduled posts. Go to the Workspace and schedule an asset for publishing.</p>
            <Link href={`/workspace/${username}`} className="bg-slate-800 hover:bg-slate-700 text-white px-6 py-3 rounded-xl transition-colors font-medium">
              Go to Workspace
            </Link>
          </div>
        ) : (
          <div className="bg-slate-900 border border-white/10 rounded-2xl overflow-hidden">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-slate-800/50 border-b border-white/5 text-xs uppercase tracking-wider text-slate-400 font-semibold">
                  <th className="p-4">Status</th>
                  <th className="p-4">Asset</th>
                  <th className="p-4">Platform / Account</th>
                  <th className="p-4">Scheduled For</th>
                  <th className="p-4">Published At</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-white/5">
                {queue.map(post => (
                  <tr key={post.id} className="hover:bg-slate-800/20 transition-colors">
                    <td className="p-4">
                      <div className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-lg border text-sm font-medium ${getStatusColor(post.status)}`}>
                        {getStatusIcon(post.status)}
                        {post.status}
                        {post.retryCount > 0 && <span className="ml-1 text-xs opacity-75">(Retry {post.retryCount})</span>}
                      </div>
                      {post.errorMessage && (
                        <div className="mt-2 text-xs text-red-400 max-w-xs truncate" title={post.errorMessage}>
                          Error: {post.errorMessage}
                        </div>
                      )}
                    </td>
                    <td className="p-4">
                      <div className="text-sm font-bold text-white mb-1 line-clamp-1">{post.assetTitle}</div>
                      <div className="text-xs text-slate-500 uppercase tracking-wider font-semibold">{post.assetType}</div>
                    </td>
                    <td className="p-4">
                      <div className="text-sm text-slate-300 font-medium">{post.platform}</div>
                      <div className="text-xs text-slate-500">{post.accountName}</div>
                    </td>
                    <td className="p-4 text-sm text-slate-300">
                      {new Date(post.scheduledFor).toLocaleString()}
                    </td>
                    <td className="p-4 text-sm text-slate-300">
                      {post.publishedAt ? new Date(post.publishedAt).toLocaleString() : '-'}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </main>
    </div>
  );
}
